from pathlib import Path
import json,gzip,hashlib
B=Path(__file__).resolve().parent;ROOT=B.parents[4];sha=lambda b:hashlib.sha256(b).hexdigest();old=B/'lote_revisao35.json';m=json.loads(old.read_bytes());ref=m['fontes_provas'];archive=ROOT/ref['path'];assert sha(archive.read_bytes())==ref['sha256'];rows=[json.loads(x) for x in gzip.decompress(archive.read_bytes()).splitlines()];assert len(rows)==35 and sum(bool(x['candidato_aprovado']) for x in rows)==31;ref['registros']=35;m['antecedente_preservado']={'path':str(old.relative_to(ROOT)),'sha256':sha(old.read_bytes()),'sucessao':'Corrige somente contagem descritiva do arquivo de provas para 35. Arquivo gzip, 31 candidatos, pareceres e replays permanecem idênticos.'};p=B/'lote_revisao35_v2.json';assert not p.exists();p.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n');files=[Path(__file__),B/'preparar_revisao35.py',B/'pareceres35.json',B/'preparo100_v2.json',B/'replay100_v2.json',B/'render100_input_v2.json',B/'render100_marked_v2.json',B/'QA.log',p,archive]+[ROOT/r['candidato'] for r in m['publicaveis_privados']];lp=B/'entrega-v2-paths.txt';lp.write_text('\n'.join(str(p.relative_to(ROOT)) for p in files)+'\n');(B/'entrega-v2-hashes.json').write_text(json.dumps({'sha256_lista':sha(lp.read_bytes()),'arquivos':[{'path':str(p.relative_to(ROOT)),'sha256':sha(p.read_bytes())} for p in files]},indent=2)+'\n');print('Manifesto final:',len(rows),'fontes,',31,'candidatos;',len(files),'arquivos')
